package com.slotix.reservationcore.availability;
import com.slotix.reservationcore.common.TenantAccessService; import com.slotix.reservationcore.resource.ResourceRepository; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import org.springframework.web.server.*; import java.util.*;
@Service public class AvailabilityRuleService { final AvailabilityRuleRepository rules; final ResourceRepository resources; final TenantAccessService access; public AvailabilityRuleService(AvailabilityRuleRepository a,ResourceRepository b,TenantAccessService c){rules=a;resources=b;access=c;} @Transactional public AvailabilityRuleResponse create(UUID companyId,UUID resourceId,CreateAvailabilityRuleRequest q){access.requireActiveMembership(companyId);if(!q.endLocalTime().isAfter(q.startLocalTime()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,"The availability interval is invalid");resources.findByIdAndCompanyIdAndDeletedAtIsNull(resourceId,companyId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Resource not found"));return AvailabilityRuleResponse.from(rules.save(AvailabilityRule.create(companyId,resourceId,q.weekday(),q.startLocalTime(),q.endLocalTime(),q.effectiveFrom(),q.effectiveTo())));} @Transactional(readOnly=true) public List<AvailabilityRuleResponse> list(UUID c,UUID r){access.requireActiveMembership(c);return rules.findByCompanyIdAndResourceIdAndDeletedAtIsNullOrderByWeekdayAscStartLocalTimeAsc(c,r).stream().map(AvailabilityRuleResponse::from).toList();}}
